//! Dictionary / language model.
//!
//! Reads `data/bopomofo-lm.tsv`, generated by `data/build.mjs` from McBopomofo's
//! MIT-licensed data. Each row is `reading<TAB>word<TAB>log10_probability`.
//!
//! The format is deliberately plain text and is shared byte-for-byte with the
//! TypeScript reference implementation, so the two engines cannot drift apart in
//! what they think the language model says.

use std::collections::{HashMap, HashSet};
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::Path;

use crate::syllable::split_reading;

#[derive(Debug, Clone, PartialEq)]
pub struct Entry {
    pub word: String,
    pub score: f64,
    pub reading: String,
    /// number of syllables the word spans
    pub syllables: usize,
}

#[derive(Debug, Clone, Copy)]
pub struct DictionaryOptions {
    /// hard cap on how many syllables one dictionary word may cover
    pub max_word_syllables: usize,
    /// keep at most this many candidates per reading
    pub max_candidates_per_reading: usize,
}

impl Default for DictionaryOptions {
    fn default() -> Self {
        // 200 matches CANDIDATE_CAP in the engine, so the loader is not a
        // second, lower ceiling than the candidate window. It was 128, which
        // stayed invisible while data/build.mjs capped every reading at 100.
        Self { max_word_syllables: 10, max_candidates_per_reading: 200 }
    }
}

#[derive(Debug, Default)]
pub struct Dictionary {
    by_reading: HashMap<String, Vec<Entry>>,
    readings: Vec<String>,
    max_word_syllables: usize,
    size: usize,
}

impl Dictionary {
    pub fn load(path: impl AsRef<Path>) -> std::io::Result<Dictionary> {
        Self::load_with(path, DictionaryOptions::default())
    }

    /// Load the language model, optionally followed by a shortcuts file.
    ///
    /// A shortcut is an extra entry in the same format with a score high enough to
    /// sort first — not a second kind of thing. Concatenating the text is enough:
    /// `from_text` already rejects an empty word and already sorts by score, so no
    /// new mechanism is needed and no shell has to change to get the feature.
    pub fn load_with_shortcuts(
        path: impl AsRef<Path>,
        shortcuts: Option<&Path>,
        options: DictionaryOptions,
    ) -> std::io::Result<Dictionary> {
        let mut text = std::fs::read_to_string(&path)?;
        if let Some(extra) = shortcuts {
            // Optional by design: a data directory without the file is a working
            // installation that simply has no shortcuts.
            if let Ok(more) = std::fs::read_to_string(extra) {
                text.push('\n');
                text.push_str(&more);
            }
        }
        Ok(Dictionary::from_text(&text, options))
    }

    pub fn load_with(path: impl AsRef<Path>, options: DictionaryOptions) -> std::io::Result<Dictionary> {
        Ok(Dictionary::from_text(&std::fs::read_to_string(path)?, options))
    }

    /// Build from the compiled TSV *text*.
    ///
    /// Reading the file is the caller's job, in the same shape as the TypeScript
    /// side: it is what lets a platform shell feed the same bytes from whatever
    /// filesystem API it has.
    fn from_text(text: &str, options: DictionaryOptions) -> Dictionary {
        let mut dict = Dictionary { max_word_syllables: 1, ..Default::default() };
        let mut max_span = 1usize;

        for line in text.lines() {
            let line = line;
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let mut parts = line.splitn(3, '\t');
            let (Some(reading), Some(word), Some(score)) =
                (parts.next(), parts.next(), parts.next())
            else {
                continue;
            };
            let Ok(score) = score.trim().parse::<f64>() else { continue };
            if reading.is_empty() || word.is_empty() {
                continue;
            }
            let syllables = split_reading(reading).len();
            let list = dict.by_reading.entry(reading.to_string()).or_insert_with(|| {
                dict.readings.push(reading.to_string());
                Vec::new()
            });
            // First-come-wins, exactly like the reference: the data is already
            // ordered best-first within a reading by the build step.
            if list.len() >= options.max_candidates_per_reading {
                continue;
            }
            list.push(Entry {
                word: word.to_string(),
                score,
                reading: reading.to_string(),
                syllables,
            });
            dict.size += 1;
            max_span = max_span.max(syllables);
        }

        // Stable sort by score descending: ties keep file order, matching
        // JavaScript's Array.prototype.sort.
        for list in dict.by_reading.values_mut() {
            list.sort_by(|a, b| b.score.total_cmp(&a.score));
        }
        dict.max_word_syllables = max_span.min(options.max_word_syllables);
        dict
    }

    pub fn lookup(&self, reading: &str) -> &[Entry] {
        self.by_reading.get(reading).map(Vec::as_slice).unwrap_or(&[])
    }

    pub fn readings(&self) -> &[String] {
        &self.readings
    }

    pub fn size(&self) -> usize {
        self.size
    }

    pub fn max_word_syllables(&self) -> usize {
        self.max_word_syllables
    }
}

/// The set of legal syllables, derived from the dictionary rather than typed by
/// hand: a syllable is legal iff some word in the language model is read that way.
pub fn build_syllable_inventory(path: impl AsRef<Path>) -> std::io::Result<HashSet<String>> {
    let file = File::open(path)?;
    let mut set = HashSet::new();
    for line in BufReader::new(file).lines() {
        let line = line?;
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let Some((reading, _)) = line.split_once('\t') else { continue };
        for s in split_reading(reading) {
            set.insert(s.to_string());
        }
    }
    Ok(set)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn lm_path() -> std::path::PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../data/bopomofo-lm.tsv")
    }

    #[test]
    fn shortcuts_sort_first_and_do_not_replace_the_model() {
        // The shipped phrase table, read the way `engine_create` reads it: from the
        // same directory as the language model, optional.
        let shortcuts = Path::new(env!("CARGO_MANIFEST_DIR")).join("../data/shortcuts.tsv");
        let plain = Dictionary::load(lm_path()).unwrap();
        let with = Dictionary::load_with_shortcuts(lm_path(), Some(&shortcuts), Default::default())
            .unwrap();

        // Without the file, the language model's own word leads.
        assert_eq!(plain.lookup("ㄉㄧˋ-ㄓˇ")[0].word, "地址");
        // With it, the phrase leads and the model's word is still behind it.
        let words: Vec<&str> = with.lookup("ㄉㄧˋ-ㄓˇ").iter().map(|e| e.word.as_str()).collect();
        assert_eq!(words[0], "台北市忠孝東路四段 100 號 5 樓");
        assert!(words.contains(&"地址"), "model word disappeared: {words:?}");
        // Every entry the phrase table adds is one entry; nothing else moves.
        assert_eq!(with.size(), plain.size() + 3);
    }

    #[test]
    fn a_missing_shortcuts_file_is_not_an_error() {
        let missing = Path::new("/nonexistent/shortcuts.tsv");
        let dict = Dictionary::load_with_shortcuts(lm_path(), Some(missing), Default::default())
            .unwrap();
        assert_eq!(dict.lookup("ㄉㄧˋ-ㄓˇ")[0].word, "地址");
    }

    #[test]
    fn loads_the_shipped_language_model() {
        let dict = Dictionary::load(lm_path()).unwrap();
        assert!(dict.size() > 100_000, "expected >100k entries, got {}", dict.size());
        assert_eq!(dict.lookup("ㄋㄧˇ-ㄏㄠˇ")[0].word, "你好");
        assert_eq!(dict.lookup("ㄨㄛˇ-ㄞˋ-ㄋㄧˇ")[0].score, -5.398);
    }

    #[test]
    fn inventory_matches_the_reference_count() {
        let inv = build_syllable_inventory(lm_path()).unwrap();
        assert_eq!(inv.len(), 1413, "the reference derives exactly 1,413 legal syllables");
    }
}
